BEGIN_HEADER_EPILOGUE
inline void dqm_config::dal::DQNode::__dummy__() const { ; }
END_HEADER_EPILOGUE
BEGIN_PRIVATE_SECTION
friend class DQTemplateParameter;
friend class DQTemplateRegion;
END_PRIVATE_SECTION

BEGIN_HEADER_PROLOGUE
class ConsistencyCheck;
END_HEADER_PROLOGUE
BEGIN_PRIVATE_SECTION
friend class ::ConsistencyCheck;
friend class DQTemplateRegion;
std::string m_tokens;
END_PRIVATE_SECTION

BEGIN_PRIVATE_SECTION

mutable std::mutex m_mutex;

mutable struct Instances : public std::map<std::string, const DQLayout*>
{
    ~Instances() { 
	std::for_each(begin(), end(), 
 		[](std::pair<const std::string,const DQLayout*> & p) { delete p.second; } );
    }
} m_instances;
END_PRIVATE_SECTION

BEGIN_PRIVATE_SECTION

mutable std::mutex m_mutex;

mutable struct Instances : public std::map<std::string, std::vector<const DQParameter*>>
{
    ~Instances() { std::for_each(begin(), end(), 
    		[](std::pair<const std::string,std::vector<const DQParameter*>> & p) {
			std::for_each(p.second.begin(), p.second.end(), 
                		[](const DQParameter*r){ delete r; });
		} );
    }

} m_instances;
END_PRIVATE_SECTION

BEGIN_PRIVATE_SECTION

mutable std::mutex m_mutex;

mutable struct Instances : public std::map<std::string, const DQReference*>
{
    ~Instances() { 
	std::for_each(begin(), end(), 
 		[](std::pair<const std::string,const DQReference*> & p) { delete p.second; } );
    }
} m_instances;
END_PRIVATE_SECTION

BEGIN_PRIVATE_SECTION

mutable std::mutex m_mutex;

mutable struct Instances : public std::map<std::string, std::vector<const DQRegion*>>
{
    ~Instances() { std::for_each(begin(), end(), 
    		[](std::pair<const std::string,std::vector<const DQRegion*>> & p) {
			std::for_each(p.second.begin(), p.second.end(), 
                		[](const DQRegion*r){ delete r; });
		} );
    }

} m_instances;
END_PRIVATE_SECTION
